import sqlite3
import sys
import requests
import json

def parse_filters():
    filters = {}
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split('=', 1)
        if len(parts) != 2:
            continue
        column, value = parts
        if column in ['id', 'name', 'source', 'created_at']:
            filters[column] = value
    return filters

def build_query(filters):
    if not filters:
        return "SELECT id, name, source, created_at FROM events"
    conditions = []
    for column, value in filters.items():
        conditions.append(f"{column} = ?")
    query = f"SELECT id, name, source, created_at FROM events WHERE {' AND '.join(conditions)}"
    return query, list(filters.values())

def main():
    if len(sys.argv) != 3:
        print("Usage: python forward_events.py <database_path> <webhook_url>")
        sys.exit(1)

    db_path = sys.argv[1]
    webhook_url = sys.argv[2]

    filters = parse_filters()
    query, params = build_query(filters)

    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()
        cursor.execute(query, params)
        rows = cursor.fetchall()
        conn.close()
    except sqlite3.Error as e:
        print(f"Database error: {e}")
        sys.exit(1)

    data = []
    for row in rows:
        event = {
            'id': row[0],
            'name': row[1],
            'source': row[2],
            'created_at': row[3]
        }
        data.append(event)

    try:
        response = requests.post(webhook_url, json=data, headers={'Content-Type': 'application/json'})
        status_code = response.status_code
        print(status_code)
        sys.exit(0 if 200 <= status_code < 300 else 1)
    except requests.RequestException as e:
        print(f"Request failed: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()
